/* База задач прошлых олимпиад. Собрана из открытых источников:
   архив oj.uz (там же можно сдавать решения), официальный сайт IOI ioinformatics.org (условия, тесты, разборы)
   и Codeforces (тренировки и раунды-зеркала олимпиад).
   Строка: [id, олимпиада, год/сезон, тур, название, сколько человек решили на oj.uz, тип, ссылка на официальный PDF, источник, рейтинг Codeforces].
   Источник: '' — задача на oj.uz (https://oj.uz/problem/view/<id>) или только PDF (id вида IOIxx_pN);
             'esep' — задача на esep-old.cpfed.kz (id = esep_<код>); 'url' — условие открывается по ссылке из 8-го поля;
             'gym' — тур целиком в тренировках Codeforces (id = gym<номер>); 'cf' — задача из архива Codeforces (id = номер задачи). */
